 require_once(__DIR__ . '/../../init.php'); class med_fluorography_importadani { private $db; private $preventType; private $extraParams; private $errorMsg = ""; public function getStudies($params) { $this->log("***ВЫПОЛНЕНИЕ ИМПОРТА***"); $result = new stdClass(); $this->dateFrom = isEmptyProperty($params, 'dateFrom'); $this->dateTo = isEmptyProperty($params, 'dateTo'); if ($this->getSettings()) { $this->preventType = isUndefinedProperty($params, 'preventType'); $response = $this->connectToAdani($params); if ($response && $response['status'][1][0] === "2") { $records = $this->XML2JSON($response['body']); if (isEmptyProperty($records, 'Patient')) { $this->log("[2]Получено обследований от АДАНИ: " . count($records->Patient)); $result = $this->groupStudy($records->Patient); $this->log("[6]В результате получено записей: " . $this->getCount($result)); if (!empty((array) $result)) { $result->errorMsg = $this->errorMsg; $this->log("***ОПЕРАЦИЯ ИМПОРТА ЗАВЕРШЕНА***\n"); return $result; } else { $this->errorMsg .= "За данный период новых записей не обнаружено.</br>"; } } else { $this->log("[2]Получено обследований от АДАНИ: " . count(isEmptyProperty($records, 'Patient'))); $this->log("[6]За данный период записей не обнаружено."); $this->errorMsg .= "За данный период записей не обнаружено.</br>"; } } else { $server = isEmptyProperty($this->extraParams, 'adaniServer'); $this->log("[1]Не удалось подключиться к серверу АДАНИ по адресу $server .", 2); $this->errorMsg .= "Не удалось подключиться к серверу АДАНИ.</br>"; } } $result->errorMsg = $this->errorMsg; $this->log("***ОПЕРАЦИЯ ИМПОРТА ЗАВЕРШЕНА***\n"); return $result; } private function getCount($records) { $count = 0; foreach ($records as $record) { $count += count((array) $record); } return $count; } private function log($message, $type = 0) { app_log($message, $type, 'medFluorographyImportAdani'); } function groupStudy($records) { $group = new stdClass(); $telMedData = []; $dbh = $this->connectToTelemed(); if ($dbh) { $sqlTeleMed = <<< "EOT"
