$stmt = $db->prepare($sqlInsert); if (is_object($records)) { $records = [$records]; } $db->beginTransaction(); try { foreach ($records as $row) { $stmt->execute([ $enterpriseCode, $preventType, isUndefinedProperty($row, 'PatientCode'), isUndefinedProperty($row->Study, 'StudyDate'), isUndefinedProperty($row->Study, 'StudyID'), $enterpriseCode, isUndefinedProperty($row->Study, 'Report'), isUndefinedProperty($row, 'Recommendation') ]); } $db->commit(); } catch (Throwable $e) { $db->rollback(); throw $e; } return true; } public function checkConnection($params) { $this->log("***ПРОВЕРКА ПОДКЛЮЧЕНИЯ***"); $this->extraParams = new stdClass(); $result = ""; $this->extraParams->adaniServer = $params->server; $this->dateFrom = $params->dateFrom; $this->dateTo = $params->dateTo; $result .= "Подключение к web-серверу Пульмоскан: "; $ret = $this->connectToAdani(); if ($ret && $ret['status'][1][0] === "2") { $result .= "ОК.</br>"; } else { $this->log("[1]Не удалось подключиться к серверу АДАНИ по адресу $params->server", 2); $result .= "Ошибка.</br>"; } $result .= "Подключение к Telemed: "; if ($params->host && $params->base) { $this->extraParams->teleMedHost = $params->host; $this->extraParams->teleMedBase = $params->base; $dbh = $this->connectToTelemed(); $result .= $dbh ? "ОК." : "Ошибка."; } else { $result .= "Нет."; } $this->log("***ОПЕРАЦИЯ ПРОВЕРКИ ПОДКЛЮЧЕНИЯ ЗАВЕРШЕНА***\n"); return $result; } private function connectToAdani() { $server = isEmptyProperty($this->extraParams, 'adaniServer'); if (trim($server) !== '') { $this->log("[1]Подключение к серверу АДАНИ ..."); $request = new stdClass(); $request->url = "http://" . trim($server) . "/cgi-bin/InsRepWM.exe/report"; $request->proxy = null; $request->param = array( 'StudyDateFrom' => $this->dateFrom, 'StudyDateTo' => $this->dateTo ); $ret = httpGET($request); $this->log($ret ? $ret['status'][2] : "Ошибка", 3); return $ret; } } private function connectToTelemed() { $host = isEmptyProperty($this->extraParams, 'teleMedHost'); $base = isEmptyProperty($this->extraParams, 'teleMedBase'); if ($host && $base) { try { $path = safe_explode('/', $host); $port = count($path) > 1 ? $path[1] : 3050; $waitTimeoutInSeconds = 15; $this->log("[3]Подключение к серверу telemed..."); $fp = fsockopen($host, $port, $errCode, $errStr, $waitTimeoutInSeconds); $this->log("OK", 3); fclose($fp); } catch (Throwable $e) { $this->log("Ошибка", 3); $this->log(mb_convert_encoding("[3]" . $errStr, "UTF-8", 'Windows-1251'), 2); $this->errorMsg .= "Не удалось подключиться к серверу телемедицины.</br>"; return false; } try { $path = $host . ":" . $base; $this->log("[4]Подключение к базе teleMed..."); $dbh = new \PDO("firebird:$path", 'SYSDBA', 'masterkey'); $this->log("ОК", 3); return $dbh; } catch (Throwable $ex) { $this->log("Ошибка", 3); $this->log("[4]" . $ex->getMessage(), 2); $this->errorMsg .= "Не удалось подключиться к базе телемедицины.</br>"; return false; } } } } handleJsonRpc('med_fluorography_importadani'); 